import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  items: {},
  totalCount: 0,
  totalPrice: 0,
};

const cart = createSlice({
  name: "cart",
  initialState,
  reducers: {
    changeItemsCount(state, { payload: { cartItem } }) {
      const { id, count, price } = cartItem;

      if (state.items[id]) {
        state.items[id].count += count;
      } else {
        state.items[id] = cartItem;
      }

      if (state.items[id].count === 0) {
        delete state.items[id];
      }

      state.totalCount += count;
      state.totalPrice += price;
    },
    clearItems(state) {
      state.items = {};
      state.totalCount = 0;
      state.totalPrice = 0;
    },
  },
});

export const selectCart = (store) => store.cart;
export const { changeItemsCount, clearItems } = cart.actions;
export default cart.reducer;
